# frozen_string_literal: true

# Keep API documentation generated by Rswag deterministic.
#
# Response bodies are recorded as examples in the documentation. Some values
# like database ids of newly created records or signed Active Storage URLs
# change on every run. Register replacements for them and they are applied
# to the documented example only. The actual response stays untouched so that
# you can still test the real values:
#
#   run_test! do
#     order = enterprise.distributed_orders.first
#     replace_in_docs("orders/#{order.id}" => "orders/10001")
#
#     expect(response.body).to include "orders/#{order.id}"
#   end
#
# Patterns can be strings or regular expressions, just like with `gsub`.
# Replacements are applied in the order they are registered.
#
# Note: In Rails 8, `response.body` returns a new string on every call.
# Modifying it in place with `gsub!` has no effect any more.
module SwaggerDocsHelper
  # Replacements applied to all documented responses.
  GLOBAL_REPLACEMENTS = {
    # Signed blob ids and variant keys change with every run.
    %r{/rails/active_storage/[0-9A-Za-z/=-]*/([^/.]+)\.png} => '/rails/active_storage/url/\1.png',
  }.freeze

  def replace_in_docs(replacements)
    swagger_docs_replacements.merge!(replacements)
  end

  def swagger_docs_replacements
    @swagger_docs_replacements ||= GLOBAL_REPLACEMENTS.dup
  end

  # The response body as it should appear in the documentation.
  def documented_response_body
    swagger_docs_replacements.reduce(response.body) do |body, (pattern, replacement)|
      body.gsub(pattern, replacement)
    end
  end
end

RSpec.configure do |config|
  config.include SwaggerDocsHelper, type: :request
end
